"""Tips = the student texts of a flat's top findings (generated by app.llm, template fallback)."""
from __future__ import annotations


def tips_for_flat(state, flat_id: str, limit: int = 3) -> list[dict]:
    out = []
    for f in state.flat_findings(flat_id)[:limit]:
        t = f["student_text"]
        o = t["output"]
        out.append({
            "finding_id": f["id"], "flat_id": flat_id, "status": f["status"], "wording": f["wording"],
            "responsibility": f["responsibility"],
            "title": o["title"], "text": f"{o['body']} {o['action']}", "cta": o["cta"],
            "source": t["source"], "prompt_version": t["prompt_version"],
            "horizon": "28d measured + annual projection", "assumptions": f["assumptions"],
        })
    return out
